export const dayKey=at=>new Date(new Date(at).getTime()+8*3600000).toISOString().slice(0,10);
export const shiftDay=(day,n)=>new Date(Date.parse(day+'T12:00:00Z')+n*86400000).toISOString().slice(0,10);
export function dateRange(days,now=new Date()){const to=dayKey(now);return{from:days?shiftDay(to,1-days):'',to:days?to:''}}
export function demoUsage(){
 const today=dayKey(new Date()),rows=[];
 const models=[['DEEPSEEK','deepseek-demo'],['QWEN','qwen-demo'],['KIMI','kimi-demo']];
 for(let i=0;i<180;i++){if(i%6===0)continue;const [provider,model]=models[i%3],input=1200+(i*137)%6000,output=200+(i*37)%1600,cached=i%4?Math.floor(input*.65):0;rows.push({task_id:'DEMO-'+i,event_id:'sample-'+i,at:shiftDay(today,-i)+'T04:00:00.000Z',day:shiftDay(today,-i),customer:i%2?'星河科技':'青禾电商',feature:i%2?'竞品研究':'内容生产',agent:'root',provider,model,requested_model:model,source:'demo',input_tokens:input,output_tokens:output,cached_tokens:cached,cost:(input-cached+cached*.2+output*3)/1e4,currency:'CNY',basis:'demo',duration_ms:800+i*11,status:i%13?'success':'failed',pricing:null})}
 return rows;
}
export function filterUsage(rows,p){return rows.filter(r=>(!p.get('from')||(r.day&&r.day>=p.get('from')))&&(!p.get('to')||(r.day&&r.day<=p.get('to')))&&['provider','model','customer','feature','source','project'].every(k=>!p.get(k)||r[k]===p.get(k)))}
export function aggregateUsage(rows){const sum=k=>{const known=rows.filter(r=>r[k]!==null&&r[k]!==undefined);return known.length?known.reduce((n,r)=>n+r[k],0):null};return{requests:rows.length,tasks:new Set(rows.map(r=>r.task_id)).size,active_days:new Set(rows.filter(r=>r.day).map(r=>r.day)).size,cost:sum('cost')??0,input_tokens:sum('input_tokens'),output_tokens:sum('output_tokens'),cached_tokens:sum('cached_tokens'),cache_known_input:rows.filter(r=>r.cached_tokens!=null).reduce((n,r)=>n+(r.input_tokens||0),0),successes:rows.filter(r=>r.status==='success').length,unknown_usage:rows.filter(r=>r.input_tokens==null||r.output_tokens==null).length,unpriced_requests:rows.filter(r=>r.basis==='unpriced').length,estimated_requests:rows.filter(r=>['reserved_estimate','telemetry_estimate','rate_estimate'].includes(r.basis)).length}}
export function demoQuery(all,p){const rows=filterUsage(all,p).sort((a,b)=>(b.at||'').localeCompare(a.at||'')),groups=new Map(),daily=new Map();for(const r of rows){const k=JSON.stringify([r.provider,r.model]);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r);if(r.day){if(!daily.has(r.day))daily.set(r.day,[]);daily.get(r.day).push(r)}}const offset=Number(p.get('offset')||0),limit=Number(p.get('limit')||50);return{summary:aggregateUsage(rows),models:[...groups.values()].map(rs=>({provider:rs[0].provider,model:rs[0].model,...aggregateUsage(rs)})).sort((a,b)=>b.cost-a.cost),daily:[...daily].sort(([a],[b])=>a.localeCompare(b)).map(([day,rs])=>({day,...aggregateUsage(rs)})),rows:rows.slice(offset,offset+limit),offset,limit,undated:{count:0,cost:0},options:{models:[...new Map(all.map(r=>[JSON.stringify([r.provider,r.model]),{provider:r.provider,model:r.model}])).values()],customers:[...new Set(all.map(r=>r.customer))],features:[...new Set(all.map(r=>r.feature))],sources:[...new Set(all.map(r=>r.source))],projects:[...new Set(all.map(r=>r.project).filter(Boolean))]}}}
export function csv(rows){const fields=['at','task_id','event_id','provider','model','customer','feature','input_tokens','output_tokens','cached_tokens','cache_creation_tokens','reasoning_tokens','project','session_id','cost','currency','basis','duration_ms','status','source'];const cell=v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,"'$&").replaceAll('"','""')+'"';return '\ufeff'+fields.join(',')+'\r\n'+rows.map(r=>fields.map(k=>cell(r[k])).join(',')).join('\r\n')}
